function materializeSurface(surface) {
  if (surface.type === 'ramp') {
    const { minX, maxX, minZ, maxZ, maxTop, axis, lowY, highY } = surface;
    const lowEnd = axis === 'x' ? minX : minZ;
    const highEnd = axis === 'x' ? maxX : maxZ;
    const span = (highEnd - lowEnd) || 1;
    const dy = highY - lowY;
    // type/axis/lowY/highY are kept on the materialized surface so bot-side
    // consumers (nav grid, surface-aware LoS) can reason about the slope.
    return { minX, maxX, minZ, maxZ, maxTop, type: 'ramp', axis, lowY, highY, heightAt(x, z) {
      const v = axis === 'x' ? x : z;
      const t = (v - lowEnd) / span;
      const c = Math.max(0, Math.min(1, t));
      return lowY + dy * c;
    } };
  }
  if (surface.type === 'plane') {
    // a sloped floor in any direction: y0 at the rectangle's (minX, minZ) corner, gx and gz the rise per unit
    // along x and z (the glTF maps' slopes; the axis ramp above is the case of one axis)
    const { minX, maxX, minZ, maxZ, maxTop, y0, gx, gz } = surface;
    return { minX, maxX, minZ, maxZ, maxTop, type: 'plane', y0, gx, gz, heightAt(x, z) { return y0 + gx * (x - minX) + gz * (z - minZ); } };
  }
  const { minX, maxX, minZ, maxZ, maxTop, top } = surface;
  return { minX, maxX, minZ, maxZ, maxTop, heightAt: () => top };
}

function buildGeneratedArena(mapKey) {
  const data = GENERATED_ARENA_COLLISION_DATA[mapKey];
  return {
    mapKey,
    obstacles: [...makeBoundaryObstacles(mapKey), ...data.obstacles],
    surfaces: data.surfaces.map(materializeSurface),
    spawns: ARENA_SPAWNS[mapKey]
  };
}

const ARENAS = {
  arena1: buildPlainField(),
  arena2: buildGeneratedArena('arena2'),
  factory: buildGeneratedArena('factory'),
  factory2: buildGeneratedArena('factory2'),
  square: buildGeneratedArena('square'),
  lobby: buildGeneratedArena('lobby'),
  station: buildGeneratedArena('station'),
  flashpoint: buildGeneratedArena('flashpoint'),
  airport: buildGeneratedArena('airport'),
  town: buildGeneratedArena('town')
};

// A box whose top is a floor — a surface lies on it (a deck's body, a crate, a car's roof) — is one a body steps
// onto when its feet are within SURFACE_STEP_HEIGHT of that top, so it holds no such body (physics.js boxHoldsAt).
// Marked once, the first time an arena is asked for.
function markFloorTops(arena) {
  for (const o of arena.obstacles) {
    o.floorTop = false;
    if (o.topBuffer == null) continue;   // (a wall: never stepped onto)
    for (const s of arena.surfaces) {
      if (Math.abs(s.maxTop - o.maxY) > 0.3) continue;
      if (s.minX > o.maxX + 0.01 || s.maxX < o.minX - 0.01 || s.minZ > o.maxZ + 0.01 || s.maxZ < o.minZ - 0.01) continue;
      o.floorTop = true; break;
    }
  }
  arena.floorTopsMarked = true;
}

export function getArena(mapKey) {
  const arena = ARENAS[mapKey];
  if (!arena) throw new Error(`No arena data for map: ${mapKey}`);
  if (!arena.floorTopsMarked) markFloorTops(arena);
  return arena;
}

export function getArenaObstacles(mapKey) { return getArena(mapKey).obstacles; }
export function getArenaSurfaces(mapKey) { return getArena(mapKey).surfaces; }
export function getArenaSpawns(mapKey) { return getArena(mapKey).spawns; }
// Modelled maps (client buildGlbArena): the play extent, and the collision data's own boxes without
// the runtime perimeter — the offline client raises its own perimeter (addBoundaryIndicator).
export function getArenaBounds(mapKey) { return MAP_BOUNDARY[mapKey] ?? { halfX: 138, halfZ: 138 }; }
export function getGeneratedObstacles(mapKey) { return GENERATED_ARENA_COLLISION_DATA[mapKey]?.obstacles ?? []; }
